// Disposable full-board CSS + actual Studio preview renderer + simulated remote link.
import {spawnSync} from 'node:child_process';
import {readFileSync,writeFileSync} from 'node:fs';
import {join,resolve} from 'node:path';
const dest=resolve(process.argv[2]||''),root=resolve(process.argv[3]||new URL('../../..',import.meta.url).pathname);if(!process.argv[2])throw Error('Diretório novo obrigatório');
const r=spawnSync(process.execPath,[join(root,'campaign-director/tests/fixtures/live-sync-focus-demo.mjs'),dest,root],{encoding:'utf8'});if(r.status)throw Error(r.stderr);
const web=join(dest,'public'),html=readFileSync(join(web,'quadro/index.html'),'utf8'),release=html.includes('live01b4')?'live01b4':'live01b3';
const input=`import {defaultCamera,lightingProfile} from './campaign-director/dist/cinematic-direction-model.js?v=${release}';
async function lightInput(){const blob=new Blob([await(await fetch('./qa-media/palco.png')).arrayBuffer()],{type:'image/png'}),imageId=await imageKey(blob),camera=defaultCamera(),lighting=lightingProfile();camera.from.zoom=camera.to.zoom=1.24;Object.assign(lighting,{enabled:true,intensity:.18,darkness:.30,vignette:.65,spots:[]});return {blob,item:{id:'parity',name:'Luz de teste',imageId,motion:'breath',seconds:12,intensity:20,ending:'loop',hold:0,fadeIn:0,fadeOut:0,camera,lighting}};}`;
// Relative requests in the board use ../qa-media; Studio renderer uses ./qa-media.
let qa=readFileSync(join(web,'live-board-qa.js'),'utf8');qa+='\n'+input.replace("import {defaultCamera,lightingProfile}","import {defaultCamera as b4Camera,lightingProfile as b4Lighting}").replace('camera=defaultCamera(),lighting=lightingProfile()','camera=b4Camera(),lighting=b4Lighting()').replace("fetch('./qa-media", "fetch('../qa-media")+`\nconst light=document.createElement('button');light.id='qaLight';light.textContent='Apresentar luz de teste';light.onclick=async()=>{const {blob,item}=await lightInput();await qaLink.present({userId:window.CRIS_IDENTITY.userId,boardCampaignId:window.CRISBridge.campaignId},{campaignId:'qa',pageId:'theater',sceneId:'test'},item,blob);};document.querySelector('#qaTools').append(light);\n`;
writeFileSync(join(web,'live-board-qa.js'),qa);
// The cold-decoder hook must import the exact production module identity.
writeFileSync(join(web,'quadro/index.html'),html.replaceAll('cinematic-frame.js?v=live01b3','cinematic-frame.js?v='+release));
writeFileSync(join(web,'parity-studio.html'),`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><link rel="stylesheet" href="campaign-director/dist/styles.css"><link rel="stylesheet" href="campaign-director/dist/cinematic.css?v=${release}"><body style="margin:0;background:#000"><div class="cinematic-studio-preview cinematic-frame" style="position:fixed;inset:0;width:100%;height:100%;max-height:none;margin:0;border:0" hidden></div><script type="module">
import {CinematicFrame} from './campaign-director/dist/cinematic-frame.js?v=${release}';import {imageKey} from './campaign-director/dist/cinematic-media.js?v=${release}';${input}
const frame=new CinematicFrame(document.querySelector('.cinematic-frame'));window.B4_PREVIEW={frame,async show(){const {blob,item}=await lightInput();return frame.show(blob,item);}};
</script></body></html>`);
writeFileSync(join(web,'parity.html'),`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><style>body{margin:0;background:#16120f;color:#eadbc3;font:13px system-ui}nav{display:flex;gap:8px;align-items:center;padding:8px}button,select{padding:8px}iframe{border:0;display:block;width:100%;height:470px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:8px}.pair iframe{height:951px}pre{white-space:pre-wrap}h2{font-size:14px}</style><nav><button id="connect">Conectar mesa fictícia</button><button id="show">Apresentar mesma luz</button><button id="seek">Pausar em 2 s</button><button id="stop">Encerrar</button><select id="width"><option>1865</option><option>1440</option><option>390</option></select></nav><p>DataConnection SIMULADO. Quadro real com todas as folhas de estilo. Preview usa o componente CinematicFrame do Studio e CSS de produção; dados fictícios.</p><h2>Prévia Studio (16:9)</h2><iframe id="studio" src="parity-studio.html" style="width:1280px;height:720px"></iframe><div class="pair"><section><h2>Quadro mestre (viewport larga)</h2><iframe id="host"></iframe></section><section><h2>Quadro remoto</h2><iframe id="player"></iframe></section></div><pre id="report"></pre><script type="module" src="parity-qa.js"></script></html>`);
writeFileSync(join(web,'parity-qa.js'),`const $=s=>document.querySelector(s),q=(w,s)=>w.document.querySelector(s),sleep=ms=>new Promise(r=>setTimeout(r,ms)),until=async f=>{for(let i=0;i<300;i++){if(f())return;await sleep(50);}throw Error('QA timeout');};const key='b4-parity-'+crypto.randomUUID();$('#host').src='quadro/?case='+key+'&visual=1&transport=simulated';$('#player').src='quadro/?case='+key+'&visual=1&transport=simulated&user=parity-'+key;const host=$('#host').contentWindow,player=$('#player').contentWindow,studio=$('#studio').contentWindow;for(const frame of [$('#host'),$('#player')])frame.style.width='1865px';
$('#connect').onclick=async()=>{await until(()=>q(host,'#masterStart')&&q(player,'#vwGo'));q(host,'#masterStart').click();await until(()=>q(host,'#shCodeB')?.textContent.length>6);q(player,'#vwRoom').value=q(host,'#shCodeB').textContent;q(player,'#vwGo').click();await until(()=>host.CRIS_LIVE_DIAGNOSTICS?.().connections===1);$('#report').textContent='Mesa fictícia conectada';};
$('#show').onclick=async()=>{await studio.B4_PREVIEW.show();q(host,'#qaLight').click();};$('#seek').onclick=async()=>{await until(()=>player.demoBoardFrame?.playing&&host.demoBoardFrame?.playing);for(const frame of [studio.B4_PREVIEW.frame,host.demoBoardFrame,player.demoBoardFrame]){frame.pause();frame.seek(2);}$('#report').textContent=JSON.stringify({at:2,frames:[studio.B4_PREVIEW.frame,host.demoBoardFrame,player.demoBoardFrame].map(f=>({time:f.time(),motion:f.item.motion,intensity:f.item.intensity,lighting:f.item.lighting,world:f.composition.world.getBoundingClientRect().toJSON(),atmosphere:f.element.querySelectorAll('.cinematic-atmosphere').length}))},null,2);};$('#stop').onclick=()=>{studio.B4_PREVIEW.frame.clear({immediate:true});q(host,'#qaCinematicStop').click();};$('#width').onchange=e=>{for(const frame of [$('#host'),$('#player')])frame.style.width=e.target.value+'px';};`);
console.log(dest);
